package dev.mineagent.runtime.neoforge.ui;
import com.fasterxml.jackson.databind.*;import dev.mineagent.runtime.core.resources.ResourceLibrary;import dev.mineagent.runtime.neoforge.MineAgentRuntimeServices;import dev.mineagent.runtime.neoforge.network.UiPayloads;import net.minecraft.server.level.ServerPlayer;import java.util.*;import java.util.concurrent.*;import java.util.function.*;import java.io.*;
/** Owner-bound preview and optional framebuffer capture; neither path executes generated code. */
public final class ServerResourceViews {
 private static final ObjectMapper JSON=new ObjectMapper();private static final ExecutorService IO=Executors.newVirtualThreadPerTaskExecutor();
 private record Capture(ServerPlayer viewer,UUID agent,UUID world,Object level,BooleanSupplier current,CompletableFuture<ResourceLibrary.Resource> future,ByteArrayOutputStream bytes,int[] total){}
 private static final Map<UUID,Capture> CAPTURES=new ConcurrentHashMap<>();
 public static CompletableFuture<ResourceLibrary.Resource> capture(ServerPlayer p,UUID agent,JsonNode args,BooleanSupplier current){
  var config=MineAgentRuntimeServices.config(p.level().getServer());if(!config.flag("resource.capture."+p.getUUID(),false))return CompletableFuture.failedFuture(new IllegalStateException("GAME_CAPTURE_DISABLED: enable optional game screenshots in model capabilities settings"));
  UUID id=UUID.randomUUID();var future=new CompletableFuture<ResourceLibrary.Resource>();var pending=new Capture(p,agent,MineAgentRuntimeServices.worldId(p.level().getServer()),p.level(),current,future,new ByteArrayOutputStream(),new int[]{-1});CAPTURES.put(id,pending);future.orTimeout(15,TimeUnit.SECONDS).whenComplete((r,e)->CAPTURES.remove(id,pending));
  p.level().getServer().execute(()->send(p,id,Map.of("kind","capture","previewId",args.path("preview_id").asText(""),"scope","minecraft-framebuffer-only")));return future;
 }
 public static void reply(ServerPlayer p,UiPayloads.Command packet){var capture=CAPTURES.get(packet.requestId());if(capture==null||capture.viewer()!=p)return;try{
  if(!capture.current().getAsBoolean()||p.level()!=capture.level()||p.level().getServer().getPlayerList().getPlayer(p.getUUID())!=p)throw new IllegalStateException("CAPTURE_CONTEXT_CHANGED");var data=JSON.readTree(packet.json());if(data.has("error"))throw new IllegalArgumentException(data.path("error").asText());int total=data.path("total").asInt(-1),offset=data.path("offset").asInt(-1);if(total<33||total>dev.mineagent.runtime.api.model.ModelImage.MAX_BYTES||offset!=capture.bytes().size()||capture.total()[0]!=-1&&capture.total()[0]!=total)throw new IllegalArgumentException("CAPTURE_SEQUENCE");capture.total()[0]=total;byte[] chunk=Base64.getDecoder().decode(data.path("data").asText());if(chunk.length<1||chunk.length>18000||chunk.length>total-offset)throw new IllegalArgumentException("CAPTURE_CHUNK");capture.bytes().writeBytes(chunk);if(capture.bytes().size()!=total)return;CAPTURES.remove(packet.requestId(),capture);byte[] image=capture.bytes().toByteArray();var root=p.level().getServer().getServerDirectory().resolve("mineagent-runtime-data");CompletableFuture.supplyAsync(()->{try{var prepared=dev.mineagent.runtime.worker.resources.ResourceImages.prepare(image,List.of(),"high");return new ResourceLibrary(root,capture.world(),p.getUUID()).save("game-view.png","image/png","minecraft:client_view",prepared.image().bytes(),null,Map.of("capturedAt",Long.toString(System.currentTimeMillis())));}catch(Exception e){throw new CompletionException(e);}},IO).whenComplete((r,e)->{if(e==null)capture.future().complete(r);else capture.future().completeExceptionally(e);});
 }catch(Exception error){CAPTURES.remove(packet.requestId(),capture);capture.future().completeExceptionally(error);}}
 public static CompletableFuture<Map<String,Object>> preview(ServerPlayer p,UUID agent,ResourceLibrary.Resource resource,JsonNode args,BooleanSupplier current){
  var server=p.level().getServer();var world=MineAgentRuntimeServices.worldId(server);var root=server.getServerDirectory().resolve("mineagent-runtime-data");return CompletableFuture.supplyAsync(()->{try{var library=new ResourceLibrary(root,world,p.getUUID());var parsed=dev.mineagent.runtime.worker.resources.ResourceParser.read(library,resource.id(),args);byte[] image=null;if(parsed.get("detectedType").equals("image"))image=dev.mineagent.runtime.worker.resources.ResourceImages.prepare(library.read(resource.id()),List.of(),"high").image().bytes();return new AbstractMap.SimpleEntry<>(parsed,image);}catch(Exception e){throw new CompletionException(e);}},IO).thenCompose(data->{var result=new CompletableFuture<Map<String,Object>>();server.execute(()->{try{if(!current.getAsBoolean()||server.getPlayerList().getPlayer(p.getUUID())!=p)throw new IllegalStateException("RESOURCE_VIEW_CONTEXT");UUID id=UUID.randomUUID();byte[] bytes=data.getValue();send(p,id,Map.of("kind","preview","name",resource.name(),"resource",resource.id().toString(),"content",data.getKey(),"total",bytes==null?0:bytes.length));if(bytes!=null)for(int at=0;at<bytes.length;at+=18000)send(p,id,Map.of("kind","preview_chunk","offset",at,"data",Base64.getEncoder().encodeToString(Arrays.copyOfRange(bytes,at,Math.min(bytes.length,at+18000)))));result.complete(Map.of("status","PREVIEW_SENT","resource_id",resource.id(),"preview_id",id,"executed",false));}catch(Exception e){result.completeExceptionally(e);}});return result;});
 }
 private static void send(ServerPlayer p,UUID id,Map<String,Object> body){try{net.neoforged.neoforge.network.PacketDistributor.sendToPlayer(p,new UiPayloads.Event(id,"resourceView",JSON.writeValueAsString(body)));}catch(Exception e){throw new IllegalStateException("RESOURCE_VIEW_ENCODING",e);}}
 private ServerResourceViews(){}
}
